<?php require_once '../includes/auth.php';require_login();verify_csrf();$u=user();$date=$_POST['attendance_date']??today();$code=$_POST['institution_code']??$u['institution_code'];if(!is_admin()&&!is_sub_officer())$code=$u['institution_code'];foreach($_POST['student_ids']??[] as $id){$id=(int)$id;$st=$_POST['status'][$id]??'present';$rm=trim($_POST['remarks'][$id]??'');if(!in_array($st,['present','absent','leave'],true))continue;$q=mysqli_prepare($conn,"SELECT institution_type,institution_code FROM students WHERE id=?");mysqli_stmt_bind_param($q,'i',$id);mysqli_stmt_execute($q);$student=mysqli_fetch_assoc(mysqli_stmt_get_result($q));if(!$student||$student['institution_code']!==$code)continue;$s=mysqli_prepare($conn,"INSERT INTO student_attendance(student_id,attendance_date,status,remarks,marked_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),remarks=VALUES(remarks),marked_by=VALUES(marked_by)");mysqli_stmt_bind_param($s,'isssi',$id,$date,$st,$rm,$u['id']);mysqli_stmt_execute($s);}log_activity('updated','attendance','Saved student presenty');flash('success','Student attendance saved.');redirect('attendance.php?date='.urlencode($date));
